let toastTimer;function toast(msg){const el=$('.toast');el.textContent=msg;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),3400)}
function openModal(title,html){lastFocus=document.activeElement;$('#modal-title').textContent=title;$('#modal-body').innerHTML=html;$('#modalback').hidden=false;document.body.style.overflow='hidden';$('.modal').focus()}
