function showEvent(id){const e=events.find(x=>x.id===id)||cards.find(x=>x.id===id);if(!e){toast('未找到该事件');return}const t=e.time!=null?e.time:Math.round((e.start_ms||0)/1000);const end=e.end!=null?e.end:Math.round((e.end_ms||e.start_ms||0)/1000);seek(t);const l1=(e.layer1||[])[0];const l2=e.layer2||null;const l3=(Array.isArray(e.layer3)&&e.layer3[0])||(e.layer3&&!Array.isArray(e.layer3)?e.layer3:null);const z1=l1&&l1.z!=null?fmtZ(l1.z):(e.z!=null?(String(e.z).includes('σ')?e.z:e.z+'σ'):'暂无');const z2=l2&&l2.z!=null?fmtZ(l2.z):'暂无';const z3=l3&&l3.z!=null?fmtZ(l3.z):'暂无';const marker=e.marker||((e.layer1||[]).map(x=>x.name||x.code).filter(Boolean).slice(0,2).join(' / '))||'相关特征';const key=e.key||((e.keywords||[]).join('、'))||'—';const type=e.type||e.trigger||'—';const dur=e.duration!=null?e.duration:Math.max(1,end-t);openModal('特殊内容 · 三层对比',`<p class="modaldesc">${e.id} / ${e.topic||'—'} / ${fmt(t)}–${fmt(end)}　<span class="badge amber">${type}</span></p><div class="comparison"><div><small>01 · 本人全局基线</small><b>${z1}</b><span>${l1?(l1.name||l1.code)+' '+(l1.direction||''):'事件相对全局偏差'}</span></div><div><small>02 · 本人其他主题</small><b>${z2}</b><span>${l2?('相对其他主题 · '+(l2.marker||'')+' · 排名 '+(l2.rank||'—')+'/'+(l2.of||'—')):'暂无主题间对比'}</span></div><div><small>03 · 同类词其他出现</small><b>${z3}</b><span>${l3?('「'+key+'」个体内对比'):(key!=='—'?'「'+key+'」暂无同类对比':'暂无关键词对比')}</span></div></div><div class="fouranalysis"><p><strong>现象描述</strong>在${e.topic||'—'}主题段，${marker}出现相对基线偏移，事件持续 ${dur} 秒。</p><p><strong>对比说明</strong>第一层为相对本人全局基线的 Z 分数；第二层为相对其他主题；第三层为同类词其他出现（无数据则标注暂无）。</p><p><strong>趋势描述</strong>建议回看前后 30 秒并结合曲线核查原始特征变化。</p><p><strong>趋势预测 <span class="badge muted">模型假设</span></strong>${e.narrative||'若局部变化模式延续，相关特征可能继续接近基线。该假设存在不确定性，不能作为已发生事实。'}</p></div><div class="notice">三层对比数据来自当前任务 cards（layer1/layer2/layer3），仅供个体内复核参考。</div><div class="modalactions"><button class="btn" data-context="${t}">查看前后文</button><button class="btn primary" data-review="${e.id}">${icon('check')}${e.reviewed?'改为待复核':'标记为已复核'}</button></div>`)}
function selectMetric(index){currentMetric=Math.min(index,5);currentSub=index>5?index-5:0;currentSub=Math.max(0,Math.min(5,currentSub));$$('[data-detail]').forEach(b=>b.classList.toggle('active',Number(b.dataset.detail)===currentMetric));renderMetric();$('#metrics')?.scrollIntoView({behavior:'smooth',block:'start'})}
function seek(value){if(!isReport){location.href=reportLink('summary',value);return}const video=$('#local-video');currentTime=Math.max(0,Math.min(duration,Number(value)||0));if(!video.hidden&&Number.isFinite(video.duration)){video.currentTime=Math.min(currentTime,video.duration)}updateTime();}
function updateTime(){if(!isReport)return;$('#current-time').textContent=fmt(currentTime);$('#stage-time').textContent=fmt(currentTime);$('#video-seek').value=currentTime;const t=(topics&&topics.length)?(topics.find(t=>currentTime>=t.start&&currentTime<t.end)||topics[topics.length-1]):null;if($('#current-topic'))$('#current-topic').textContent=t?t.name:'—';let index=transcript.findLastIndex(t=>t.time<=currentTime);$$('[data-transcript]').forEach((el,i)=>el.classList.toggle('active',i===index));}
function setPlaying(value){if(!isReport)return;playing=value;$$('.play-control,.playoverlay').forEach(b=>{b.innerHTML=icon(playing?'pause':'play');b.setAttribute('aria-label',playing?'暂停':'播放')});$('.playoverlay').style.opacity=playing?'0':'1';}
function togglePlay(){if(!isReport)return;const video=$('#local-video');if(!video.hidden){if(video.paused)video.play().catch(()=>toast('视频暂时无法播放，请换用浏览器支持的 MP4 文件。'));else video.pause();return}if(currentTime>=duration)currentTime=0;setPlaying(!playing)}
const logData={task_id:task.id,models:{pipeline:versions.pipeline,indicators:versions.indicators,rules:versions.rules,topics:versions.topics,grid_ms:versions.grid_ms,deepseek:deepseek.model||null},config:{baseline:'within_task_valid_intervals',grid_ms:versions.grid_ms||100,grid_note:versions.grid_note||''},coverage,deepseek,stages:(__boot.logData&&__boot.logData.stages)||['queued','extracting','scoring','done'],source:'portrait'};
function download(content,name,type){const blob=new Blob([content],{type});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();window.dispatchEvent(new CustomEvent('psytrace-export',{detail:{name}}));setTimeout(()=>URL.revokeObjectURL(url),10000);toast('数据文件已导出')}
function exportData(format,scope='full'){const portrait=__boot.portrait||null;let obj={task_id:task.id,note:'真实 portrait 导出',task,metrics:metrics.map(({values,...m})=>m),extended,topics,events,alerts,cards,transcript,coverage,versions,deepseek,logs:logData,portrait};if(scope==='metrics')obj={task_id:task.id,metrics:obj.metrics,extended,versions};if(scope==='events')obj={task_id:task.id,events,alerts,cards};if(format==='json')download(JSON.stringify(obj,null,2),`${task.id}-${scope}.json`,'application/json;charset=utf-8');if(format==='logs')download(JSON.stringify(logData,null,2),`${task.id}-logs.json`,'application/json;charset=utf-8');if(format==='txt')download('语音转写文本\n'+transcript.map(t=>`${fmt(t.time)} [${t.topic}] ${t.text}`).join('\n'),`${task.id}-transcript.txt`,'text/plain;charset=utf-8');if(format==='csv'){let rows;if(scope==='events')rows=[['event_id','start_s','end_s','topic','trigger','marker','z_score','reviewed'],...events.map(e=>[e.id,e.time,e.end,e.topic,e.type,e.marker,e.z,e.reviewed])];else if(scope==='metrics')rows=[['metric','value','unit','baseline','delta'],...metrics.slice(0,5).map(m=>[m.name,m.score,m.unit,m.baseline,m.delta]),...extended.map(e=>[e.name,e.value,e.unit,'',e.delta])];else rows=[['timestamp_s','topic','marker','value','unit','baseline','source'],...Array.from({length:Math.max(1,Math.ceil((duration||1)/10))},(_,i)=>{let t=i*10;return markerData.map((m,j)=>{let base=baseMarker[j],curve=markerCurve(j),at=t/(duration||1)*(curve.length-1),low=Math.floor(at),high=Math.min(low+1,curve.length-1);let v=curve[low]+(curve[high]-curve[low])*(at-low);return [t,topics.find(p=>t>=p.start&&t<p.end)?.name||'其他',m.name,Number(v).toFixed(3),m.unit,base,'series']})}).flat()];const cell=v=>{let s=String(v);if(/^[=+\-@]/.test(s)&&!/^[-+]?\d+(\.\d+)?$/.test(s))s="'"+s;return '"'+s.replaceAll('"','""')+'"'};download('\ufeff'+rows.map(r=>r.map(cell).join(',')).join('\r\n'),`${task.id}-${scope}.csv`,'text/csv;charset=utf-8');}}
