if(isReport&&task.video_url){const v=$('#local-video');if(v){v.src=task.video_url;v.hidden=false;v.controls=true;v.onloadedmetadata=()=>{duration=v.duration||duration;$('#video-seek').max=duration;$('#duration').textContent=fmt(duration);$('#local-file-state').textContent=task.file||'任务视频';$('#video-label').textContent='任务视频';};v.ontimeupdate=()=>{currentTime=v.currentTime;updateTime()};v.onplay=()=>setPlaying(true);v.onpause=()=>setPlaying(false);}}

