const actions={close:closeModal,export:showExport,play:togglePlay,menu:()=>$('.sidebar').classList.toggle('open'),fullscreen:()=>{$('#video-stage')?.requestFullscreen?.().catch(()=>toast('浏览器暂不支持全屏，请使用原生视频全屏按钮'))},context:()=>showContext(),logs:showLogs,fileinfo:()=>openModal('原始视频文件信息',`<p class="modaldesc">当前任务视频可通过报告页播放；亦可载入本地文件复核。</p><div class="comparison" style="grid-template-columns:1fr 1fr"><div><small>文件名称</small><span style="display:block;margin-top:8px;word-break:break-all;color:#b1c5e8">${task.file}</span></div><div><small>视频时长</small><b>${fmt(task.duration||0)}</b><span>任务时长</span></div></div><div class="notice">可在视频分析报告中载入本地视频，体验播放、定位与复核。该操作仅在本机读取，不会上传文件。</div><div class="modalactions"><a class="btn primary" href="report.html">进入视频复核 ${icon('arrow')}</a></div>`),notifications:()=>openModal('任务通知',`<a href="report.html" class="finding"><div class="findicon">${icon('check')}</div><div class="findingbody"><div class="findingtitle">分析完成 · ${task.id}</div><div class="findingdesc">09:38 · 六类指标与报告已生成</div></div>${icon('arrow')}</a><a href="${reportLink('special')}" class="finding"><div class="findicon amber">${icon('warning')}</div><div class="findingbody"><div class="findingtitle">${events.filter(e=>!e.reviewed).length} 项内容待人工复核</div><div class="findingdesc">点击查看触发原因与三层对比</div></div>${icon('arrow')}</a>`),account:()=>openModal('研究员工作空间',`<p class="modaldesc">本地分析工作空间 · 角色：研究员</p><div class="notice">当前可浏览分析任务、进行本地复核标记与导出真实数据。账号与权限由本地部署配置。</div>`),settings:()=>openModal('显示设置',`<p class="modaldesc">调整本机报告的显示密度。设置仅对当前页面生效。</p><label class="field">界面字号<select id="font-size-setting"><option value="13">标准</option><option value="14">稍大</option><option value="15">大字号</option></select></label><div class="modalactions"><button class="btn primary" data-action="apply-settings">应用设置</button></div>`),'apply-settings':()=>{const val=$('#font-size-setting').value;document.documentElement.style.zoom=String(Number(val)/13);closeModal();toast('显示设置已更新')},help:()=>openModal('页面使用说明',`<div class="fouranalysis"><p><strong>01 · 从总览进入报告</strong>点击指标、重点发现或快捷入口，即可进入对应章节。两个页面共享同一份分析任务数据。</p><p><strong>02 · 联动复核</strong>主题条、转写句子、曲线采样点和热力图色块都可定位时间。未加载视频时可拖动时间轴；可载入本地视频体验实际回看。</p><p><strong>03 · 三层对比</strong>点击特殊内容中的“三层对比”，查看与本人全局基线、其他主题和同类词的对比，并标记复核状态。</p><p><strong>04 · 导出</strong>支持 JSON、CSV 与转写文本。PDF 使用浏览器打印保存，建议开启“背景图形”。</p></div><div class="notice">页面完全本地运行，无外部字体、脚本或网络服务。复核状态存于当前浏览器本地存储。</div>`),'confirm-export':()=>{const scope=$('#export-scope').value;if(exportFormat==='pdf'){closeModal();if(page!=='report'){location.href=reportLink('summary') .replace('#summary','?print=1&scope='+scope+'#summary');return}printReport(scope)}else{exportData(exportFormat,scope);closeModal()}}};
function printReport(scope){
 closeModal();setPlaying(false);
 const ids=scope==='metrics'?['summary','metrics']:scope==='events'?['special','alerts']:null;
 const hide=ids?$$('.reportsection').filter(s=>!ids.includes(s.id)):[];
 hide.forEach(el=>el.hidden=true);
 const savedMetric=currentMetric,savedSub=currentSub;
 let printBlock=null;
 if(scope!=='events'){
   printBlock=document.createElement('div');printBlock.className='printonly printmetrics';
   const states=[...metrics.map((m,i)=>[i,0]),...[1,2,3,4,5].map(i=>[5,i])];
   for(const [category,sub] of states){currentMetric=category;currentSub=sub;renderMetric();const part=document.createElement('div');part.className='printmetricpart';const heading=document.createElement('h3');heading.textContent=category===5?extended[sub].name:metrics[category].name;part.append(heading);const clone=document.createElement('div');clone.innerHTML=$('#metric-content').innerHTML;part.append(clone);printBlock.append(part);}
   currentMetric=savedMetric;currentSub=savedSub;renderMetric();$('#metrics').append(printBlock);$('#metrics').classList.add('print-expanded');
 }
 const cleanup=()=>{hide.forEach(el=>el.hidden=false);printBlock?.remove();$('#metrics').classList.remove('print-expanded');window.removeEventListener('afterprint',cleanup)};
 window.addEventListener('afterprint',cleanup);window.print();
}
